#!/usr/bin/env python3
"""Aggregate inference results and evaluate against gold annotations."""
import json
import argparse
import random
from pathlib import Path
from collections import defaultdict, Counter


def load_gold(gold_file):
    gold = {}
    doc_tokens = {}
    with open(gold_file) as f:
        for line in f:
            doc = json.loads(line.strip())
            entities = set()
            for ent in doc["entities"]:
                entities.add((ent["text"], ent["type"]))
            gold[doc["doc_key"]] = entities
            doc_tokens[doc["doc_key"]] = doc["tokens"]
    return gold, doc_tokens


def load_results(results_dir):
    results = defaultdict(dict)
    for rf in sorted(Path(results_dir).glob("test_shard_*_n*.jsonl")):
        with open(rf) as f:
            for line in f:
                r = json.loads(line.strip())
                key = (r["n_candidates"], r["seed"])
                results[key][r["doc_key"]] = r["candidates"]
    return results


def locate_spans(entities, tokens):
    """Find all token-level spans for each entity. Stores (start, end_exclusive) tuples."""
    if not tokens:
        for ent in entities:
            if "spans" not in ent:
                ent["spans"] = []
        return
    if entities and "spans" in entities[0]:
        return
    token_text = " ".join(tokens)
    char_to_token = {}
    pos = 0
    for i, tok in enumerate(tokens):
        for j in range(len(tok)):
            char_to_token[pos + j] = i
        pos += len(tok) + 1
    for ent in entities:
        text = ent["text"]
        spans = []
        search_pos = 0
        while True:
            idx = token_text.find(text, search_pos)
            if idx < 0:
                break
            s = char_to_token.get(idx)
            ec = idx + len(text) - 1
            e = char_to_token.get(ec)
            if s is not None and e is not None:
                spans.append((s, e + 1))
            search_pos = idx + 1
        ent["spans"] = spans


def entity_iou(e1, e2):
    """Max token-level IoU across all span pairs. 0 if types differ."""
    if e1["type"] != e2["type"]:
        return 0.0
    spans1 = e1.get("spans", [])
    spans2 = e2.get("spans", [])
    if not spans1 or not spans2:
        return 0.0
    best = 0.0
    for s1, e1e in spans1:
        for s2, e2e in spans2:
            inter = max(0, min(e1e, e2e) - max(s1, s2))
            union = (e1e - s1) + (e2e - s2) - inter
            iou = inter / union if union > 0 else 0.0
            if iou > best:
                best = iou
    return best


def iou_agreement_score(cand_ents, all_ents, tau=0.5):
    """Per-entity agreement: fraction of other candidates with IoU >= tau match."""
    if not cand_ents:
        return 0.0
    scores = []
    for ent in cand_ents:
        has_spans = bool(ent.get("spans"))
        support = []
        for other in all_ents:
            if other is cand_ents:
                continue
            if has_spans:
                best = max((entity_iou(ent, e) for e in other), default=0.0)
                support.append(1.0 if best >= tau else 0.0)
            else:
                m = any(e["text"] == ent["text"] and e["type"] == ent["type"] for e in other)
                support.append(1.0 if m else 0.0)
        avg = sum(support) / len(support) if support else 0.0
        scores.append(avg)
    return sum(scores) / len(scores)


def compute_f1(pred_entities, gold_entities):
    pred_set = set()
    for e in pred_entities:
        pred_set.add((e["text"], e["type"]))
    if not pred_set and not gold_entities:
        return 1.0, 1.0, 1.0
    if not pred_set or not gold_entities:
        return 0.0, 0.0, 0.0
    tp = len(pred_set & gold_entities)
    p = tp / len(pred_set)
    r = tp / len(gold_entities)
    f1 = 2 * p * r / (p + r) if (p + r) > 0 else 0.0
    return p, r, f1


def self_consistency_score(candidates):
    n = len(candidates)
    if n <= 1:
        return [1.0]
    entity_sets = []
    for c in candidates:
        entity_sets.append(set((e["text"], e["type"]) for e in c["entities"]))
    scores = []
    for i, eset in enumerate(entity_sets):
        if not eset:
            scores.append(0.0)
            continue
        total = 0.0
        for entity in eset:
            count = sum(1 for j in range(n) if j != i and entity in entity_sets[j])
            total += count / (n - 1)
        scores.append(total / len(eset))
    return scores


def weighted_vote_entities(candidates):
    n = len(candidates)
    counter = Counter()
    for c in candidates:
        for e in c["entities"]:
            counter[(e["text"], e["type"])] += 1
    threshold = n / 2
    return [{"text": t, "type": tp} for (t, tp), cnt in counter.items() if cnt > threshold]


def evaluate_setting(doc_results, gold, strategy="greedy", doc_tokens=None, tau=0.5):
    total_tp = total_pred = total_gold = 0
    per_doc_f1 = []
    for doc_key, candidates in doc_results.items():
        if doc_key not in gold:
            continue
        gold_ents = gold[doc_key]
        if strategy == "greedy":
            pred = candidates[0]["entities"]
        elif strategy == "self_consistency":
            scores = self_consistency_score(candidates)
            best_idx = max(range(len(scores)), key=lambda i: scores[i])
            pred = candidates[best_idx]["entities"]
        elif strategy == "iou_self_consistency":
            tokens = doc_tokens.get(doc_key, []) if doc_tokens else []
            all_ents = []
            for c in candidates:
                locate_spans(c["entities"], tokens)
                all_ents.append(c["entities"])
            sc = [iou_agreement_score(ents, all_ents, tau=tau) for ents in all_ents]
            best_idx = max(range(len(sc)), key=lambda i: sc[i])
            pred = candidates[best_idx]["entities"]
        elif strategy == "weighted_vote":
            pred = weighted_vote_entities(candidates)
        elif strategy == "oracle":
            best_f1 = -1
            pred = []
            for c in candidates:
                _, _, f1 = compute_f1(c["entities"], gold_ents)
                if f1 > best_f1:
                    best_f1 = f1
                    pred = c["entities"]
        elif strategy == "random":
            random.seed(42)
            pred = random.choice(candidates)["entities"]
        else:
            raise ValueError(f"Unknown: {strategy}")
        pred_set = set((e["text"], e["type"]) for e in pred)
        tp = len(pred_set & gold_ents)
        total_tp += tp
        total_pred += len(pred_set)
        total_gold += len(gold_ents)
        _, _, f1 = compute_f1(pred, gold_ents)
        per_doc_f1.append(f1)
    micro_p = total_tp / max(total_pred, 1)
    micro_r = total_tp / max(total_gold, 1)
    micro_f1 = 2 * micro_p * micro_r / (micro_p + micro_r) if (micro_p + micro_r) > 0 else 0.0
    macro_f1 = sum(per_doc_f1) / max(len(per_doc_f1), 1)
    return {
        "micro_p": round(micro_p, 4), "micro_r": round(micro_r, 4),
        "micro_f1": round(micro_f1, 4), "macro_f1": round(macro_f1, 4),
        "total_tp": total_tp, "total_pred": total_pred, "total_gold": total_gold,
        "num_docs": len(per_doc_f1),
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--results_dir", required=True)
    parser.add_argument("--gold_file", required=True)
    parser.add_argument("--output_file", required=True)
    args = parser.parse_args()
    gold, doc_tokens = load_gold(args.gold_file)
    print(f"Loaded {len(gold)} gold documents")
    all_results = load_results(args.results_dir)
    print(f"Found {len(all_results)} (n, seed) settings")

    strategies_multi = [
        ("self_consistency", {}),
        ("iou_self_consistency", {"tau": 0.3}),
        ("iou_self_consistency", {"tau": 0.5}),
        ("iou_self_consistency", {"tau": 0.7}),
        ("weighted_vote", {}),
        ("oracle", {}),
        ("random", {}),
    ]

    final = {}
    n_values = sorted(set(n for n, _ in all_results.keys()))
    for n in n_values:
        seeds = sorted([s for n2, s in all_results.keys() if n2 == n])
        strats = [("greedy", {})] if n == 1 else strategies_multi
        for strategy, kwargs in strats:
            tau = kwargs.get("tau", 0.5)
            label = f"iou_sc_tau{str(tau).replace('.', '')}" if strategy == "iou_self_consistency" else strategy
            seed_results = []
            for seed in seeds:
                key = (n, seed)
                if key not in all_results:
                    continue
                result = evaluate_setting(
                    all_results[key], gold, strategy,
                    doc_tokens=doc_tokens, tau=tau,
                )
                result["seed"] = seed
                seed_results.append(result)
            if seed_results:
                f1s = [r["micro_f1"] for r in seed_results]
                mean_f1 = sum(f1s) / len(f1s)
                std_f1 = (sum((x - mean_f1) ** 2 for x in f1s) / (len(f1s) - 1)) ** 0.5 if len(f1s) > 1 else 0.0
                setting_key = f"n{n}_{label}"
                final[setting_key] = {
                    "n": n, "strategy": label, "seeds": seeds,
                    "mean_micro_f1": round(mean_f1 * 100, 2),
                    "std_micro_f1": round(std_f1 * 100, 2),
                    "per_seed": seed_results,
                }
                print(f"N={n:2d} {label:25s}: F1={mean_f1*100:.2f} +/- {std_f1*100:.2f}")

    parse_summary = {}
    parse_by_n = defaultdict(list)
    for pf in sorted(Path(args.results_dir).glob("parse_stats_*.json")):
        with open(pf) as f:
            ps = json.load(f)
            parse_by_n[ps["n_candidates"]].append(ps)
    for n in sorted(parse_by_n.keys()):
        total = sum(ps["total_parses"] for ps in parse_by_n[n])
        success = sum(ps["successful_parses"] for ps in parse_by_n[n])
        rate = success / max(total, 1)
        parse_summary[f"n{n}"] = {"total": total, "success": success, "rate_pct": round(rate * 100, 2)}
        print(f"Parse N={n}: {rate*100:.1f}% ({success}/{total})")

    output = {"results": final, "parse_stats": parse_summary, "num_gold_docs": len(gold)}
    out_path = Path(args.output_file)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nSaved to {out_path}")


if __name__ == "__main__":
